sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
        return;
    }

    var equipmentId = g_form.getValue('equipment');
    if (!equipmentId) {
        return;
    }

    g_form.hideFieldMsg('equipment');   // clear previous message

    var ga = new GlideAjax('x_2228927_equipm_0.EquipmentRequestAjax');
    ga.addParam('sysparm_name', 'getEquipmentInfo');
    ga.addParam('sysparm_equipment', equipmentId);
    ga.addParam('sysparm_quantity', g_form.getValue('quantity') || '1');

    ga.getXMLAnswer(function(answer) {
        var info = JSON.parse(answer);

        if (!info.found) {
            g_form.showFieldMsg('equipment', 'Equipment could not be found.', 'error');
            return;
        }
        if (!info.active) {
            g_form.showFieldMsg('equipment', 'This item is no longer available.', 'error');
            return;
        }

        // Live preview of what the server-side Business Rule will compute
        g_form.setValue('total_cost', 'USD;' + info.total_cost);

        if (!info.enough_stock) {
            g_form.showFieldMsg('equipment',
                'Only ' + info.stock_qty + ' in stock. The request may be delayed.', 'info');
        } else {
            g_form.showFieldMsg('equipment', info.stock_qty + ' in stock.', 'info');
        }
    });

}
